content.text:
.panel{min-width:0;background:linear-gradient(155deg,#26362d,#1b2821);border:1px solid #405347;border-radius:16px;padding:14px;display:flex;flex-direction:column;gap:10px;overflow:auto;scrollbar-width:thin}
.meter{display:grid;gap:4px}
.meterhead{display:flex;justify-content:space-between;color:var(--muted);font-size:12px}
.card{padding:10px;border-radius:12px;background:#17231c;border:1px solid var(--line)}
.card h3{margin:0 0 7px;font-size:13px;color:var(--lime)}
.kids{display:grid;gap:6px}
.tasks{font-size:12px;color:#dce4d8;display:grid;gap:4px}
.tasks .done{text-decoration:line-through;color:#8da18d}
.help{font-size:11px;color:#aebcaf;line-height:1.45;margin-top:auto}
.restart{align-self:stretch;border:1px solid #60715e;background:#2e4235;color:var(--ink);padding:9px;border-radius:10px;font-weight:700}
.panel{padding:8px;gap:7px;border-radius:11px}
.subtitle,.help{font-size:10px}
.card{padding:7px}
@media(max-height:500px){.panel{gap:5px;padding:7px}
.card{padding:6px}
.help{font-size:9px}

STYLE 1

